def pats(cl, n):
    k = len(cl)
    if k == 0:
        return ['.' * n]
    free = n - sum(cl) - (k - 1)
    if free < 0:
        return []
    res = []
    for cut in itertools.combinations(range(free + k), k):
        parts = []; prev = -1
        for x in cut:
            parts.append(x - prev - 1); prev = x
        parts.append(free + k - 1 - prev)
        s = ''
        for i in range(k):
            s += '.' * parts[i] + '#' * cl[i] + ('.' if i < k - 1 else '')
        res.append(s + '.' * parts[k])
    return res


def okcol(col, cl, done):
    rs = [len(x) for x in re.findall('#+', col)]
    if done:
        return rs == cl
    if len(rs) > len(cl):
        return False
    if not rs:
        return True
    if col[-1] == '#':
        return rs[:-1] == cl[:len(rs) - 1] and rs[-1] <= cl[len(rs) - 1]
    return rs == cl[:len(rs)]


def solve(clue):
    a, b = clue.split()
    rows = [[int(v) for v in t.split(',') if v] for t in a.split('/')]
    cols = [[int(v) for v in t.split(',') if v] for t in b.split('/')]
    R = len(rows); C = len(cols)
    P = [pats(cl, C) for cl in rows]
    grid = []

    def rec(i):
        if i == R:
            return True
        for p in P[i]:
            grid.append(p)
            if all(okcol(''.join(g[j] for g in grid), cols[j], i == R - 1) for j in range(C)):
                if rec(i + 1):
                    return True
            grid.pop()
        return False

    if rec(0):
        return '\n'.join(grid)
    return ''

